def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: datetime.timedelta
    :return: a total number of seconds (float) or None for invalid input
    """
    if value is None:
        return None
    try:
        # Pydantic/json can't serialize timedelta directly, so we convert it to a numeric value
        return value.total_seconds()
    except Exception:
        # handle non‑timedelta objects or objects missing ``total_seconds``
        return None

def dehydrate_time(value):
    """Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None
    try:
        from datetime import time as _time_type
    except Exception:
        raise TypeError("Unable to import datetime.time for type checking")
    if isinstance(value, _time_type):
        return value.isoformat()
    else:
        raise TypeError(f"dehydrate_time expects a datetime.time instance, got {type(value).__name__}")

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if value is None:
        return None

    # If it's already a dict, simply return it unchanged
    if isinstance(value, dict):
        return value

    # Validate expected attributes
    if not (hasattr(value, "lat") and hasattr(value, "lon") and hasattr(value, "time")):
        raise TypeError(
            "Expected a Point-like object with 'lat', 'lon', and 'time' attributes"
        )

    # Build the dehydrated representation
    point_dict = {"lat": value.lat, "lon": value.lon}

    # Convert time to ISO 8601 string if possible
    time_val = getattr(value, "time")
    if hasattr(time_val, "isoformat"):
        point_dict["time"] = time_val.isoformat()
    else:
        point_dict["time"] = time_val

    return point_dict

def keys(self):
    """
    Return the keys of the record.

    :return: list of key names
    """
    # Attempt to retrieve the underlying mapping that stores the record.
    # Common attribute names for such a mapping are `record` or `data`.
    # If the object itself is a dictionary, use it directly.
    try:
        # Prefer explicit record attribute if it exists
        record_map = getattr(self, "record", None)
        if record_map is None:
            # Fallback to `data` attribute
            record_map = getattr(self, "data", None)
        # If still not found, and the object behaves like a dict, use it
        if record_map is None:
            if isinstance(self, dict):
                record_map = self
            else:
                # As a last resort, try to access the object's __dict__
                record_map = getattr(self, "__dict__", None)
                if record_map is None:
                    raise AttributeError
        # Ensure we have a mapping with a keys() method
        if hasattr(record_map, "keys"):
            return list(record_map.keys())
        # If none of the strategies yields a keys() method, return empty list
        return []
    except Exception:
        # Any problem retrieving keys should result in an empty list
        return []

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    # Prefer a direct lookup if available
    if hasattr(self, "_index_lookup") and isinstance(self._index_lookup, dict):
        try:
            return self._index_lookup[key]
        except KeyError:
            raise KeyError(key)
    # Fallback to list search
    try:
        return self._index.index(key)
    except (AttributeError, ValueError):
        raise KeyError(key)

def values(self, *keys):
    """
    Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Helper to get all values in a consistent order.
    try:
        # Prefer explicit order from a dict-like interface
        all_values = list(self.values())
        all_keys = list(self.keys())
    except AttributeError:
        # Fallback: try a private attribute that might hold items.
        if hasattr(self, "_items"):
            # If _items is a container of key/value pairs.
            try:
                # Assume _items behaves like a mapping or sequence of pairs.
                if isinstance(self._items, dict):
                    all_values = list(self._items.values())
                    all_keys = list(self._items.keys())
                else:
                    # Assume sequence of tuples (key, value)
                    all_keys = [k for k, _ in self._items]
                    all_values = [v for _, v in self._items]
            except Exception as exc:
                raise RuntimeError("Unable to introspect items for values") from exc
        else:
            raise AttributeError("Object does not provide a way to access its values")

    if not keys:
        return all_values

    result = []

    for k in keys:
        if isinstance(k, int):
            # Treat as positional index.
            if 0 <= k < len(all_values):
                result.append(all_values[k])
            else:
                raise IndexError(f"Index {k} out of range for values list of length {len(all_values)}")
        else:
            # Treat as key lookup.
            try:
                # Standard dict-like access
                value = self[k]
            except (KeyError, TypeError):
                # Fallback: check if key exists in the underlying mapping
                if hasattr(self, "_items") and isinstance(self._items, dict):
                    if k in self._items:
                        value = self._items[k]
                    else:
                        raise KeyError(f"Key {k!r} not found in underlying mapping")
                else:
                    # Try attribute access
                    if hasattr(self, k):
                        value = getattr(self, k)
                    else:
                        raise KeyError(f"Key {k!r} not found in object")
            result.append(value)

    return result

def pop_u16(self):
    """ Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    try:
        # Assume the data is stored in a mutable bytearray or list of ints
        if not hasattr(self, 'data'):
            raise AttributeError("Attribute 'data' not found in the instance.")
        # Ensure there are at least two bytes to remove
        if len(self.data) < 2:
            raise ValueError("Not enough data to pop a 16-bit integer.")
        # Extract the last two bytes
        last_two = self.data[-2:]
        # Remove them from the internal buffer
        del self.data[-2:]
        # Convert from big-endian to unsigned integer
        return int.from_bytes(last_two, byteorder='big', signed=False)
    except Exception as e:
        # Re-raise with context
        raise RuntimeError(f"Failed to pop a 16-bit unsigned integer: {e}") from e

def discard(self, n=-1, qid=-1, dehydration_hooks=None,
                hydration_hooks=None, **handlers):
        """
        Appends a DISCARD message to the output queue.

        :param n: number of records to discard, default = -1 (ALL)
        :param qid: query ID to discard for, default = -1 (last query)
        :param dehydration_hooks:
            Hooks to dehydrate types (dict from type (class) to dehydration
            function). Dehydration functions receive the value and returns an
            object of type understood by packstream.
        :param hydration_hooks:
            Hooks to hydrate types (mapping from type (class) to
            dehydration function). Dehydration functions receive the value
            of type understood by packstream and are free to return anything.
        :param handlers: handler functions passed into the returned Response object
        """
        # Sanity checks
        if not isinstance(n, int):
            raise TypeError("parameter 'n' must be an integer")
        if not isinstance(qid, int):
            raise TypeError("parameter 'qid' must be an integer")

        dehydration_hooks = dehydration_hooks or {}
        hydration_hooks = hydration_hooks or {}

        for type_obj, hook in dehydration_hooks.items():
            if not isinstance(type_obj, type):
                raise TypeError("dehydration_hooks keys must be types")
            if not callable(hook):
                raise TypeError("dehydration_hooks values must be callables")

        for type_obj, hook in hydration_hooks.items():
            if not isinstance(type_obj, type):
                raise TypeError("hydration_hooks keys must be types")
            if not callable(hook):
                raise TypeError("hydration_hooks values must be callables")

        # Build the DISCARD message
        discard_msg = {
            "type": "DISCARD",
            "records_to_discard": n,
            "query_id": qid,
            "dehydration_hooks": dehydration_hooks,
            "hydration_hooks": hydration_hooks,
        }

        # Ensure there is an output queue to append to
        if not hasattr(self, "_output_queue"):
            raise AttributeError("Output queue not initialized on this instance")

        # Append the message to the queue
        self._output_queue.append(discard_msg)

        # Simple Response placeholder that holds handlers and the message
        class _DiscardResponse:
            def __init__(self, message, handlers):
                self.message = message
                self.handlers = handlers

            def __repr__(self):
                return f"<DiscardResponse handlers={list(self.handlers.keys())}>"

        return _DiscardResponse(discard_msg, handlers)

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        raise TypeError(f"Expected str, got {type(s).__name__}")
    value = s.strip()
    if not value:
        return tuple()
    if value.lower().startswith("v"):
        value = value[1:]
    parts = value.split(".")
    nums = []
    for p in parts:
        try:
            nums.append(int(p))
        except ValueError:
            raise ValueError(f"Invalid version component {p!r} from {s!r}")
    return tuple(nums)

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, func)
    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """

    def decorator(func):
        if not callable(func):
            raise TypeError('ttl_cache can only decorate callables')

        from collections import OrderedDict
        from functools import wraps

        cache = OrderedDict()
        expires = {}

        if typed:
            def make_key(args, kwargs):
                # Include argument types into the key when typed is True
                return (tuple(args), tuple(sorted(kwargs.items())), tuple(type(a) for a in args))
        else:
            def make_key(args, kwargs):
                return (tuple(args), tuple(sorted(kwargs.items())))

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs)
            now = timer()

            if key in cache:
                # Check if the cached value is still valid
                if now - expires[key] < ttl:
                    cache.move_to_end(key)          # Update LRU order
                    return cache[key]
                # Expired: remove entry
                del cache[key]
                del expires[key]

            # Compute fresh value
            result = func(*args, **kwargs)

            # Store result with current timestamp
            cache[key] = result
            expires[key] = now
            cache.move_to_end(key)

            # Enforce maxsize limit
            if len(cache) > maxsize:
                oldest_key = next(iter(cache))
                del cache[oldest_key]
                del expires[oldest_key]

            return result

        return wrapper

    return decorator

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.
    """
    def decorating_function(func):
        if maxsize is None or maxsize == 0:
            # Disable caching
            return func
        if maxsize < 0:
            raise ValueError("maxsize must be a non-negative integer or None")

        cache = {}
        order = []

        def wrapper(*args, **kwargs):
            # Construct the cache key
            if typed:
                key_args = tuple((arg, type(arg)) for arg in args)
                key_kwargs = tuple((k, (v, type(v))) for k, v in sorted(kwargs.items()))
            else:
                key_args = args
                key_kwargs = tuple(sorted(kwargs.items()))
            key = (key_args, key_kwargs)

            if key in cache:
                # Move the key to the end to mark it as recently used
                order.remove(key)
                order.append(key)
                return cache

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    def decorator(func):
        cache = {}
        usage = {}

        if maxsize <= 0:
            return func

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            if typed:
                key_args = tuple((x, type(x)) for x in args)
                key_kwargs = tuple(sorted((k, type(v), v) for k, v in kwargs.items()))
            else:
                key_args = args
                key_kwargs = tuple(sorted(kwargs.items()))

            key = (key_args, key_kwargs)

            if key in cache:
                usage[key] = usage[key] + 1
                return cache[key]

            result = func(*args, **kwargs)
            cache[key] = result
            usage[key] = 1

            if len(cache) > maxsize:
                # Evict item with lowest usage count (and one of them if ties)
                min_usage = min(usage.values())
                for k in list(cache):
                    if usage[k] == min_usage:
                        del cache[k]
                        del usage[k]
                        break
            return result

        return wrapper

    return decorator

def popitem(self):
        """Remove and return the `(key, value)` pair first inserted."""
        try:
            first_key = next(iter(self))
        except StopIteration:
            raise KeyError('The dictionary is empty')
        try:
            value = self.pop(first_key)
            return first_key, value
        except Exception as e:
            # In case self.pop fails, re-raise as KeyError for consistency
            raise KeyError(f'Error popping item: {e}') from e

def setdefault(self, key, default=None):
    """
    D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D
    """
    try:
        if key in self:
            return self[key]
        # If the key is not present, set it to the provided default
        self[key] = default
        return default
    except Exception as exc:
        # Log or re‑raise with more context if needed
        raise type(exc)(f"Error setting default for key {key!r}: {exc}") from exc

def get(self, key, default=None):
    """D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None."""
    if key in self:
        return self[key]
    return default

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    def decorator(method):
        if lock is None:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    return c[k]
                except KeyError:
                    pass  # key not found
                v = method(self, *args, **kwargs)
                try:
                    c[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    with lock(self):
                        return c[k]
                except KeyError:
                    pass  # key not found
                v = method(self, *args, **kwargs)
                try:
                    with lock(self):
                        c[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, method)
    return decorator

@staticmethod
    def file_to_textbuffer(file_name, encoding):
        """
        Load a file toward a text buffer (UTF-8), using the specify encoding while reading.
        CAUTION : This will read the whole file IN MEMORY.
        :param file_name: File name.
        :type file_name: str
        :param encoding: Encoding to use.
        :type encoding: str
        :return: A text buffer or None in case of error.
        :rtype str
        """
        try:
            if encoding:
                with open(file_name, 'r', encoding=encoding) as f:
                    return f.read()
            else:
                with open(file_name, 'r') as f:
                    return f.read()
        except Exception:
            return None

def is_file_exist(file_name):
    """
    Check if file name exist.
    :param file_name: File name.
    :type file_name: str
    :return: Return true (exist), false (do not exist, or invalid file name)
    :rtype bool
    """
    if not isinstance(file_name, str):
        return False
    if not file_name:
        return False
    try:
        return os.path.isfile(file_name)
    except Exception:
        return False

@classmethod
    def _reset_logging(cls):
        """
        Reset
        """
        import logging
        root = logging.getLogger()
        for handler in root.handlers[:]:
            root.removeHandler(handler)
        root.setLevel(logging.WARNING)

def directlyProvidedBy(object):  # pylint:disable=redefined-builtin
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    try:
        from zope.interface import providedBy
    except Exception as exc:  # pragma: no cover
        # zope.interface is not available – raise a clear error
        raise RuntimeError("zope.interface package is required for directlyProvidedBy") from exc

    try:
        decl = providedBy(object)
    except Exception as exc:  # pragma: no cover
        # If the object does not provide any interfaces, fall back to an empty declaration
        try:
            from zope.interface.interfaces import IDeclaration
            return IDeclaration()
        except Exception:
            return tuple()

    # Ensure we return a declaration object (may already be one)
    return decl

def namesAndDescriptions(self, all=False):
    """Return attribute names and descriptions defined by interface.

    Returns:
        list[tuple[str, str]]: A list of (name, description) tuples sorted
        alphabetically by name.  Hidden attributes (starting with an
        underscore) are excluded unless ``all`` is True.  Callable
        attributes are not included.
    """
    result = []

    cls = self.__class__

    # Inspect attributes defined in the class dictionary
    for name, val in vars(cls).items():
        if not all and name.startswith("_"):
            continue
        if callable(val):
            continue

        # Retrieve description
        desc = ""
        if hasattr(val, "description") and isinstance(val.description, str):
            desc = val.description
        elif isinstance(val, property):
            desc = val.fget.__doc__ or ""
        elif hasattr(val, "__doc__") and isinstance(val.__doc__, str):
            desc = val.__doc__

        result.append((name, desc.strip()))

    # Add descriptors defined via __slots__ that may not appear in vars()
    for slot in getattr(cls, "__slots__", []):
        if not all and slot.startswith("_"):
            continue
        if hasattr(cls, slot):
            val = getattr(cls, slot)
            if callable(val):
                continue

            desc = ""
            if hasattr(val, "description") and isinstance(val.description, str):
                desc = val.description
            elif isinstance(val, property):
                desc = val.fget.__doc__ or ""
            elif hasattr(val, "__doc__") and isinstance(val.__doc__, str):
                desc = val.__doc__

            result.append((slot, desc.strip()))

    # Remove duplicates that may arise from slots also being defined in vars()
    seen = set()
    unique_result = []
    for name, desc in result:
        if name not in seen:
            seen.add(name)
            unique_result.append((name, desc))

    unique_result.sort(key=lambda x: x[0])
    return unique_result

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    if not isinstance(all, bool):
        raise TypeError("'all' must be a boolean")

    seen = set()
    attribute_names = []

    for cls in self.__class__.__mro__:
        for name, value in cls.__dict__.items():
            if name in seen:
                continue
            seen.add(name)

            if not all and name.startswith('_'):
                continue
            if callable(value):
                continue
            attribute_names.append(name)

    attribute_names.sort()
    return attribute_names

def _c_optimizations_ignored():
    """
    The opposite of `_c_optimizations_required`.
    """
    try:
        return not _c_optimizations_required()
    except Exception:
        return False

def _c_optimizations_required():
    """
    Return a true value if the C optimizations are required.

    This uses the ``PURE_PYTHON`` variable as documented in `_use_c_impl`.
    """
    try:
        return not PURE_PYTHON
    except NameError:
        # If PURE_PYTHON is not defined, default to requiring C optimizations
        return True

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the stored context
    self.context = {}

    # Reinitialize the histogram bins
    # Use the existing initial_value if defined, otherwise generate new bins
    try:
        if hasattr(self, "initial_value") and self.initial_value is not None:
            # Ensure that we do not keep a reference to a mutable default
            self.bins = self.initial_value
        else:
            # Fallback to factory method, if available
            if hasattr(self, "make_bins") and callable(self.make_bins):
                self.bins = self.make_bins()
            else:
                # If no method is available, simply set bins to an empty list
                self.bins = []
    except Exception as exc:
        raise RuntimeError(f"Failed to reset histogram bins: {exc}") from exc

    # Optionally reset any aggregate counters or metadata if present
    if hasattr(self, "total_count"):
        self.total_count = 0
    if hasattr(self, "min_value"):
        self.min_value = None
    if hasattr(self, "max_value"):
        self.max_value = None
    # No explicit return value needed; mutation of the instance state is sufficient.

def to_csv(self, separator=",", header=None):
    """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
          Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.
    """
    lines = []
    if header is not None:
        lines.append(str(header))
    try:
        for point, value in self:
            # Convert point coordinates to string
            if isinstance(point, (list, tuple)):
                coord_str = separator.join(str(p) for p in point)
            else:
                coord_str = str(point)
            # Convert value parts to string
            if isinstance(value, (list, tuple)):
                value_str = separator.join(str(v) for v in value)
            else:
                value_str = str(value)
            line = separator.join([coord_str, value_str])
            lines.append(line)
    except Exception:
        # If the graph is not iterable in (point, value) form, try to iterate over
        # points only and treat values as None.
        for point in self:
            if isinstance(point, (list, tuple)):
                coord_str = separator.join(str(p) for p in point)
            else:
                coord_str = str(point)
            lines.append(coord_str)
    return "\n".join(lines) + ("\n" if lines else "")

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Exclude Source sequences directly
    if isinstance(seq, Source):
        return False
    # Single element case
    if isinstance(seq, FillRequest):
        return True
    # Strings should not be treated as sequences of FillRequest
    if isinstance(seq, (str, bytes)):
        return False
    # Try iterating over the sequence
    try:
        for element in seq:
            if isinstance(element, FillRequest):
                return True
    except TypeError:
        # Not iterable
        return False
    return False

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    try:
        return callable(getattr(obj, "fill", None)) and callable(getattr(obj, "request", None))
    except Exception:
        return False

def is_run_el(obj):
    """Object contains executable method 'run'."""
    try:
        return callable(getattr(obj, "run", None))
    except Exception:
        return False

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    try:
        return callable(getattr(obj, 'fill', None)) and callable(getattr(obj, 'compute', None))
    except Exception:
        return False

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    try:
        coord = np.asarray(coord, dtype=float)
    except Exception as exc:
        raise TypeError(f"coord must be array‑like, got {type(coord).__name__}") from exc

    if coord.ndim != 1 or coord.shape[0] != len(self.edges):
        raise ValueError(f"coord must be a 1‑D array of length {len(self.edges)}, got shape {coord.shape}")

    # protect against non‑numeric weight
    try:
        weight = float(weight)
    except Exception as exc:
        raise TypeError(f"weight must be a scalar numeric value, got {type(weight).__name__}") from exc

    indices = []
    for c, edges in zip(coord, self.edges):
        # find the bin index such that edges[idx] <= c < edges[idx+1]
        idx = np.searchsorted(edges, c, side='right') - 1
        if idx < 0 or idx >= len(edges) - 1:
            # outside the histogram – ignore
            return
        indices.append(idx)

    # increment the count in the found bin
    self.counts[tuple(indices)] += weight
    return

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.
    """

    import re

    key_regex = re.compile(r'^[A-Za-z0-9._-]+$')
    value_regex = re.compile(r'^[A-Za-z0-9._-]+$')

    errors = []

    for k, v in labels.items():
        # Validate key type and regex
        key_err = None
        try:
            if not isinstance(k, (str, bytes)):
                raise TypeError
            key_str = k.decode() if isinstance(k, bytes) else k
        except Exception:
            key_err = 'expected string or bytes-like object'
        else:
            if not key_regex.fullmatch(key_str):
                key_err = f"Label key '{key_str}' does not match the regex [...]"

        if key_err:
            errors.append({str(k): key_err})
            # skip value validation if key invalid type
            # but still try value? example shows True key error but also True value error separately
            # So we continue to validate value regardless
        # Validate value type and regex
        try:
            if not isinstance(v, (str, bytes)):
                raise TypeError
            val_str = v.decode() if isinstance(v, bytes) else v
        except Exception:
            val_err = 'expected string or bytes-like object'
        else:
            if not value_regex.fullmatch(val_str):
                val_err = f"Label value '{val_str}' does not match the regex [...]"

        if 'val_err' in locals():
            errors.append({str(v): val_err})
            # remove local var to avoid reuse
            del val_err

    if errors:
        raise ValidationError(errors)
    return None

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Together with :func:`generate_default_observer_schema_list`, this function is
    called recursively to generate part of a default ``observer_schema`` from part
    of a Kubernetes resource, defined respectively by ``manifest_dict`` or
    ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary
            represents the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces
    all non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest
    file.

    Identifying fields are considered to be ``apiVersion``, ``kind``, and the
    name and namespace inside ``metadata`` when present.
    """
    if not isinstance(manifest_dict, dict):
        # If input is not a dict, return an empty dict
        return {}
    result = {}
    # Define identifying keys for top-level schema
    top_identifiers = {"apiVersion", "kind"}
    # Assign side-effect on metadata name/namespace
    for key, value in manifest_dict.items():
        try:
            if isinstance(value, dict):
                # Special handling for top-level metadata
                if first_level and key == "metadata":
                    sub_result = {}
                    for sub_key, sub_val in value.items():
                        if sub_key in {"name", "namespace"}:
                            sub_result[sub_key] = sub_val
                        else:
                            # Recursively process nested dicts/ lists
                            if isinstance(sub_val, dict):
                                sub_result[sub_key] = generate_default_observer_schema_dict(sub_val, first_level=False)
                            elif isinstance(sub_val, list):
                                # The list processing is handled by generate_default_observer_schema_list
                                sub_result[sub_key] = None
                            else:
                                sub_result[sub_key] = None
                    result[key] = sub_result
                else:
                    result[key] = generate_default_observer_schema_dict(value, first_level=False)
            elif isinstance(value, list):
                # Delegate list handling to the corresponding function
                # Here we simply set it to None; the actual list conversion
                # should happen elsewhere in the code base.
                result[key] = None
            else:
                if first_level and key in top_identifiers:
                    result[key] = value
                else:
                    result[key] = None
        except Exception:
            # Safely ignore any unexpected type errors and set None
            result[key] = None
    return result

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Validate that the application object has the expected attributes
    if not hasattr(app, "spec"):
        raise AttributeError("The provided application object lacks a 'spec' attribute.")
    if not hasattr(app.spec, "manifest"):
        raise AttributeError("The application's spec lacks a 'manifest' attribute.")

    manifest = app.spec.manifest

    # Ensure the manifest is an iterable of resources
    if not isinstance(manifest, (list, tuple)):
        raise TypeError("app.spec.manifest must be a list or tuple of resources.")

    for resource in manifest:
        # Skip non-dict items
        if not isinstance(resource, dict):
            continue

        # Skip resources that already have a custom observer schema defined
        if resource.get("observer_schema") is not None:
            continue

        # Construct a very simple default observer schema
        #  - Reflect the resource's kind and name
        #  - Assume the resource is considered ready when its status field is present
        default_schema = {
            "kind": resource.get("kind"),
            "metadata": {
                "name": resource.get("metadata", {}).get("name")
            },
            "status": {
                "ready": True
            }
        }

        # Attach the default schema to the resource
        resource["observer_schema"] = default_schema

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    if not isinstance(prefix, str):
        raise TypeError("prefix must be a string")
    try:
        status = getattr(self, 'status')
    except AttributeError:
        raise AttributeError("Instance has no 'status' attribute")
    # Convert status to string appropriately
    if isinstance(status, str):
        status_repr = status
    elif hasattr(status, 'name'):
        status_repr = status.name
    else:
        status_repr = str(status)
    return prefix + status_repr

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    if not isinstance(prefix, str):
        raise TypeError("prefix must be a string")
    try:
        # Try common attribute names for the log
        logs = getattr(self, 'logs', None) or getattr(self, 'validation_log', None) or getattr(self, 'log', None)
        if logs is None:
            return prefix
        if not hasattr(logs, '__iter__'):
            raise TypeError("validation log is not iterable")
        parts = [f"{prefix}{str(entry)}" for entry in logs]
        return "\n".join(parts)
    except Exception:
        # Fallback to just prefix if anything goes wrong
        return prefix

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if not isinstance(inventory, dict):
        raise ValueError(f"inventory must be a dict, got {type(inventory).__name__}")

    if extract_spec_version:
        inv_type = inventory.get('type')
        # If type is a string and matches allowed types, use it as the spec_version
        allowed = getattr(self, 'allowed_types', [])
        if isinstance(inv_type, str) and inv_type in allowed:
            spec_version = inv_type
        else:
            spec_version = getattr(self, 'spec_version', None)
    else:
        spec_version = getattr(self, 'spec_version', None)

    if spec_version is None:
        raise ValueError("specification version could not be determined")

    # Example validation: ensure required top-level fields are present
    required_fields = {'name', 'type', 'version'}
    missing = required_fields - inventory.keys()
    if missing:
        missing_str = ", ".join(sorted(missing))
        raise ValueError(f"inventory is missing required field(s): {missing_str}")

    # Additional spec-specific checks would go here

    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    if manifest_files is None:
        return
    missing = []

    # Normalize manifest input: dict or iterable of (filename, digest)
    if isinstance(manifest_files, dict):
        items = manifest_files.items()
    elif isinstance(manifest_files, (list, tuple)):
        items = manifest_files
    else:
        raise TypeError(
            f"manifest_files has unsupported type {type(manifest_files)}; "
            "expected dict or list/tuple of (filename, digest) pairs"
        )

    # Make digests_used a set for fast lookup
    if digest_used := isinstance(digests_used, (set, frozenset)):
        used_set = digests_used
    else:
        used_set = set(digests_used or [])

    for filename, required_digest in items:
        file_digests = self.analyzed_files.get(filename, [])
        # File missing or digest not found for that file
        if required_digest not in file_digests:
            missing.append((filename, required_digest))
            continue
        # Digest needed but not marked as used
        if required_digest not in used_set:
            missing.append((filename, required_digest))

    if missing:
        raise ValueError(
            f"Missing or unused digests: {missing}. "
            "All digests in the manifest must be present and listed in digests_used."
        )

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Basic type check
    if not isinstance(prior, type(self)):
        raise TypeError(f"prior must be an instance of {type(self).__name__}, got {type(prior).__name__}")

    # Helper to compare two collections
    def _compare_set(name, a_attr, b_attr):
        if not hasattr(self, a_attr):
            raise AttributeError(f"Current inventory is missing attribute '{a_attr}'")
        if not hasattr(prior, b_attr):
            raise AttributeError(f"Prior inventory is missing attribute '{b_attr}'")
        a_set = set(getattr(self, a_attr))
        b_set = set(getattr(prior, b_attr))
        if a_set != b_set:
            raise ValueError(f"Mismatch in '{name}':\n  Current:  {sorted(a_set)}\n  Prior:    {sorted(b_set)}")

    # Check species and parameters for set equality
    _compare_set('species', 'species', 'species')
    _compare_set('parameters', 'parameters', 'parameters')

    # If mapping dicts exist, verify their keys and ordering
    for attr in ('name_to_index', 'index_to_name'):
        if hasattr(self, attr) and hasattr(prior, attr):
            self_map = getattr(self, attr)
            prior_map = getattr(prior, attr)
            if set(self_map.keys()) != set(prior_map.keys()):
                raise ValueError(f"Mismatch in map keys for '{attr}':\n  Current keys: {sorted(self_map.keys())}\n  Prior keys:   {sorted(prior_map.keys())}")
            # Ensure order correspondence if mapping values are indices
            if all(isinstance(v, int) for v in self_map.values()) and all(isinstance(v, int) for v in prior_map.values()):
                # sort by keys and compare lists
                self_order = [self_map[k] for k in sorted(self_map)]
                prior_order = [prior_map[k] for k in sorted(prior_map)]
                if self_order != prior_order:
                    raise ValueError(f"Ordering mismatch in '{attr}' between current and prior inventory")
        else:
            # If an attribute exists only in one side, consider it a mismatch
            missing_curr = not hasattr(self, attr)
            missing_prior = not hasattr(prior, attr)
            if missing_curr != missing_prior:
                side = "current" if missing_curr else "prior"
                raise ValueError(f"Attribute '{attr}' missing in {side} inventory")

    # Check consistency of additional dicts if present
    for dict_attr in ('constraints', 'priors'):
        if hasattr(self, dict_attr) and hasattr(prior, dict_attr):
            self_dict = getattr(self, dict_attr)
            prior_dict = getattr(prior, dict_attr)
            if set(self_dict.keys()) != set(prior_dict.keys()):
                raise ValueError(f"Mismatch in keys for '{dict_attr}':\n  Current: {sorted(self_dict.keys())}\n  Prior:   {sorted(prior_dict.keys())}")
        else:
            missing_curr = not hasattr(self, dict_attr)
            missing_prior = not hasattr(prior, dict_attr)
            if missing_curr != missing_prior:
                side = "current" if missing_curr else "prior"
                raise ValueError(f"Attribute '{dict_attr}' missing in {side} inventory")

    # All checks passed – no explicit return needed (None indicates success)

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if inventory is None:
        raise ValueError("inventory must not be None")
    if not isinstance(inventory, (dict, list, tuple)):
        raise TypeError(f"inventory must be a dict or list, got {type(inventory)}")
    if not isinstance(version, str):
        raise TypeError(f"version must be a string, got {type(version)}")

    # We assume ``inventory`` is an iterable of entries (dicts or namedtuples)
    # where each entry may have the keys ``logical_path``, ``content_files``
    # and ``version``.  If ``inventory`` is a mapping from logical paths to
    # content, we handle that case as well.
    result = {}

    # Helper to add content files for a logical path
    def _add_entry(logical_path, files):
        if logical_path not in result:
            result[logical_path] = set()
        result[logical_path].update(files)

    if isinstance(inventory, dict):
        # Mapping from logical_path -> list[content_file] or list[tuple]
        for logical_path, entry in inventory.items():
            # ``entry`` may be a list of content file paths or a dict with
            # version information etc.  We try to extract file names.
            try:
                files = set(entry) if isinstance(entry, (list, tuple)) else {entry}
            except Exception:
                continue
            _add_entry(logical_path, files)
        return result

    # Iterate over iterable entries
    for entry in inventory:
        if not isinstance(entry, (dict,)):
            # skip unknown format
            continue
        try:
            entry_version = entry.get("version")
            logical_path = entry["logical_path"]
            files = entry.get("content_files", [])
        except KeyError:
            # skip entries that don't have required keys
            continue
        # If the entry's version matches the requested version, include it.
        # Also include entries from later versions (duplicates in later
        # versions) as requested in the docstring.
        if entry_version == version or entry_version > version:
            _add_entry(logical_path, files)
    return result

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")
    if 'files' not in fixity:
        raise ValueError("Fixity block missing 'files' key")
    files = fixity['files']
    if not isinstance(files, list):
        raise ValueError("'files' in fixity block must be a list")
    for entry in files:
        if not isinstance(entry, dict):
            raise ValueError("Each file entry must be a dictionary")
        if 'filename' not in entry:
            raise ValueError("File entry missing 'filename'")
        filename = entry['filename']
        if not isinstance(filename, str):
            raise ValueError("Filename must be a string")
        if filename not in manifest_files:
            raise ValueError(f"Fixity block references unknown file: {filename}")
    return True

def files_list(path):
    """
    Return the files in `path`
    """
    import os
    if not os.path.exists(path):
        raise FileNotFoundError(f"Path does not exist: {path}")
    if os.path.isfile(path):
        return [os.path.abspath(path)]
    files = []
    for root, _, filenames in os.walk(path):
        for name in filenames:
            files.append(os.path.abspath(os.path.join(root, name)))
    return sorted(files)

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os

    if not isinstance(folder, str):
        raise TypeError("folder must be a string representing a directory path")
    if not os.path.isdir(folder):
        raise FileNotFoundError(f"Folder '{folder}' does not exist or is not a directory")

    # Find all XML files and collect their basenames
    xml_basenames = set()
    try:
        for root, dirs, files in os.walk(folder):
            for filename in files:
                base, ext = os.path.splitext(filename)
                if ext.lower() == ".xml":
                    xml_basenames.add(base)
    except OSError as e:
        raise RuntimeError(f"Error while scanning the folder '{folder}': {e}") from e

    # Group all files whose basename matches an XML basename
    packages = {}
    try:
        for root, dirs, files in os.walk(folder):
            for filename in files:
                base, _ = os.path.splitext(filename)
                if base in xml_basenames:
                    packages.setdefault(base, []).append(os.path.join(root, filename))
    except OSError as e:
        raise RuntimeError(f"Error while collecting package files in '{folder}': {e}") from e

    return packages

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path

    Returns
    -------
    dict
        Mapping from XML basename to a dict of file names and their byte contents.
    """
    import os
    import zipfile

    if not isinstance(zip_path, str):
        raise TypeError(f"zip_path must be a string, got {type(zip_path).__name__}")

    if not os.path.exists(zip_path):
        raise FileNotFoundError(f"zip_path '{zip_path}' does not exist")

    packages = {}

    try:
        with zipfile.ZipFile(zip_path, mode='r') as zin:
            # Map each folder to its XML basename (if any)
            folder_to_base = {}
            for info in zin.infolist():
                if info.is_dir():
                    continue
                fname = info.filename
                folder = os.path.dirname(fname)
                if fname.lower().endswith('.xml'):
                    basename = os.path.splitext(os.path.basename(fname))[0]
                    folder_to_base[folder] = basename

            # Group all files by the XML basename derived above
            for info in zin.infolist():
                if info.is_dir():
                    continue
                fname = info.filename
                folder = os.path.dirname(fname)
                key = folder_to_base.get(folder)
                if key:  # only include files that belong to a folder with an XML
                    if key not in packages:
                        packages[key] = {}
                    try:
                        data = zin.read(info)
                    except Exception as e:
                        # Skip this file if reading fails
                        continue
                    packages[key][fname] = data
    except zipfile.BadZipFile as e:
        raise zipfile.BadZipFile(f"Failed to read ZIP file: {e}")

    return packages

def files_list_from_zipfile(zip_path):
    """Return the files in `zip_path`."""
    # Validate the input type
    if not isinstance(zip_path, (str, bytes, os.PathLike)):
        raise TypeError("zip_path must be a string, bytes, or PathLike object")

    # Ensure the zip file exists
    if not os.path.exists(zip_path):
        raise FileNotFoundError(f"No such file: '{zip_path}'")

    try:
        with zipfile.ZipFile(zip_path, "r") as zf:
            # Collect names that are not directories
            file_names = [name for name in zf.namelist() if not name.endswith("/")]
            # Return a sorted list for consistent ordering
            return sorted(file_names)
    except zipfile.BadZipFile as exc:
        raise zipfile.BadZipFile(f"File '{zip_path}' is not a valid zip archive") from exc

def fix_namespace_prefix_w(content):
    """Convert os textos cujo padrão é `w:st="` em `w-st="`."""
    if content is None:
        return ''
    if not isinstance(content, str):
        try:
            content = content.decode('utf-8')
        except Exception as exc:
            raise TypeError("Content must be a str or bytes-like object") from exc
    return content.replace('w:st="', 'w-st="')

def match_pubdate(node, pubdate_xpaths):
    """Retorna o primeiro match da lista de pubdate_xpaths"""
    if not node or not pubdate_xpaths:
        return None
    for xpath in pubdate_xpaths:
        try:
            result = node.xpath(xpath)
        except Exception:
            continue
        if result:
            first = result[0]
            if isinstance(first, str):
                return first.strip()
            # If it's an Element get its text
            text = getattr(first, 'text', None)
            if text is not None:
                return text.strip()
            # Fallback to string conversion
            try:
                return str(first).strip()
            except Exception:
                pass
    return None

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    # Validate indent
    if not isinstance(indent, int) or indent < 0:
        indent = 0
    # Build representation
    try:
        import json
        rep = json.dumps(
            self,
            default=lambda o: getattr(o, '__dict__', str(o)),
            indent=indent,
            sort_keys=True,
        )
    except Exception:
        try:
            import pprint
            rep = pprint.pformat(self, indent=indent)
        except Exception:
            rep = repr(self)
    if debug:
        debug_info = (
            f"\nDebug: type={type(self).__name__}, "
            f"id={id(self)}, "
            f"repr={repr(self)}"
        )
        rep += debug_info
    return rep

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.
    """
    # Validate that hook is a valid HookType (or at least an accepted type)
    if not isinstance(hook, HookType):
        raise TypeError(f"Expected a HookType for hook registration, got {type(hook).__name__}")

    def decorator(func):
        """Register the function as a handler for the given hook."""
        try:
            # Use the instance's registry dictionary to store handlers per hook
            if hasattr(self, "_registry") and isinstance(self._registry, dict):
                handlers = self._registry.setdefault(hook, [])
                handlers.append(func)
            else:
                # Fallback: create a simple attribute per hook on the instance
                attr = f"_handlers_{hook}"
                if hasattr(self, attr):
                    getattr(self, attr).append(func)
                else:
                    setattr(self, attr, [func])
        except Exception as exc:
            raise RuntimeError(f"Failed to register handler for hook {hook}: {exc}") from exc
        return func

    return decorator

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def inner_func(*args, **kwargs):
        result = namefunc(*args, **kwargs)
        if PY3:
            return result
        # Python 2: ensure we return a bytestring
        if isinstance(result, bytes):
            return result
        return result.encode('utf-8')
    return inner_func

def get_versions():
    """Get version information or return default if unable to do so."""
    import sys
    try:
        import importlib.metadata as metadata
    except ImportError:
        try:
            import importlib_metadata as metadata
        except ImportError:
            return "default"

    versions = {}
    for mod_name in list(sys.modules.keys()):
        if not mod_name or not mod_name[0].isalpha():
            continue
        try:
            ver = metadata.version(mod_name)
            if ver:
                versions[mod_name] = ver
        except metadata.PackageNotFoundError:
            continue
        except Exception:
            continue
    return versions or "default"

def render(pieces, style):
    """Render the given version pieces into the requested style."""

    # Validate pieces
    if pieces is None:
        return ''
    try:
        iterator = iter(pieces)
    except TypeError:
        raise TypeError('pieces must be an iterable')
    # Validate style
    if not isinstance(style, str):
        raise TypeError('style must be a string')
    style = style.strip().lower()
    if not style:
        raise ValueError('style must not be empty')

    # Simple HTML escape function (no external imports)
    def _escape_html(s):
        return (
            s.replace("&", "&amp;")
             .replace("<", "&lt;")
             .replace(">", "&gt;")
             .replace('"', "&quot;")
             .replace("'", "&#x27;")
        )

    # Define renderer functions
    def _plain(ps):
        return ''.join(str(p) for p in ps)

    def _html(ps):
        return ''.join(_escape_html(str(p)) for p in ps)

    def _markdown(ps):
        # Placeholder: treat like plain for now
        return ''.join(str(p) for p in ps)

    renderers = {
        'plain': _plain,
        'html': _html,
        'markdown': _markdown,
    }

    renderer = renderers.get(style)
    if renderer is None:
        raise ValueError(f"Unsupported style '{style}'. Supported styles: {', '.join(renderers.keys())}")

    return renderer(iterator)

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    try:
        for piece in pieces:
            if piece == '+':
                # We already have a plus, use a dot instead
                return '.'
    except TypeError:
        raise TypeError("pieces must be an iterable of items")
    # No plus found, so return a plus
    return '+'

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import shlex

    # Build the command list
    if isinstance(commands, (list, tuple)):
        cmd_list = list(commands)
    else:
        cmd_list = [commands]

    if args:
        if isinstance(args, (list, tuple)):
            cmd_list.extend(args)
        else:
            cmd_list.append(args)

    if verbose:
        # Print the command in a shell-escaped form for readability
        print("Running command:", " ".join(shlex.quote(part) for part in cmd_list))

    # Configure stderr handling
    stderr = subprocess.DEVNULL if hide_stderr else subprocess.PIPE

    try:
        result = subprocess.run(
            cmd_list,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=stderr,
            check=False,
            universal_newlines=True
        )
    except FileNotFoundError as e:
        raise RuntimeError(f"Command not found: {cmd_list[0]!r}") from e
    except Exception as e:  # pragma: no cover
        raise RuntimeError(f"Error running command {' '.join(cmd_list)}: {e}") from e

    # Raise if the command failed
    if result.returncode != 0:
        err_msg = result.stderr.strip() if result.stderr else ""
        raise subprocess.CalledProcessError(
            result.returncode, cmd_list, output=result.stdout, stderr=err_msg
        )

    return result.stdout

def get_config():
    """Create, populate and return the VersioneerConfig() object."""
    try:
        from pathlib import Path
        import configparser
        from .config import VersioneerConfig  # assuming config module contains the class
    except Exception:
        # Fallback: try to load from global import
        from config import VersioneerConfig
    config = VersioneerConfig()
    # Determine the location of the setup.cfg file (or pyproject.toml)
    try:
        root = Path(__file__).parent
        cfg_file = root / "setup.cfg"
        if not cfg_file.is_file():
            # try pyproject.toml for VCS metadata
            cfg_file = root / "pyproject.toml"
        if cfg_file.is_file():
            parser = configparser.ConfigParser()
            try:
                print(f"Reading versioneer config from {cfg_file}")  # debug
                parser.read_file(cfg_file.open())
            except Exception:
                return config  # return defaults if parsing fails
            if parser.has_section("versioneer"):
                for key, value in parser["versioneer"].items():
                    if hasattr(config, key):
                        setattr(config, key, value)
    except Exception:
        # Any issue reading the config file results in the default config
        pass
    return config

def register_vcs_handler(vcs, method):  # type: (str, str) -> typing.Callable
    """Create decorator to mark a method as the handler of a VCS."""
    def decorator(f):
        """Store f in HANDLERS[vcs][method]."""
        if not callable(f):
            raise TypeError('Handler must be a callable')
        # Ensure the global HANDLERS dict exists
        if 'HANDLERS' not in globals():
            globals()['HANDLERS'] = {}
        HANDLERS = globals()['HANDLERS']
        # Ensure a nested dict for this vcs
        if vcs not in HANDLERS:
            HANDLERS[vcs] = {}
        elif not isinstance(HANDLERS[vcs], dict):
            raise TypeError(f'HANDLERS[{vcs!r}] must be a dict')
        HANDLERS[vcs][method] = f
        return f
    return decorator

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        tuple: (num_objects, good_objects) where num_objects is the total
        number of objects that were inspected and good_objects is the
        number of objects found to be valid.  Objects which failed
        validation are counted in the difference.
    """
    # Collect all objects in the hierarchy.  The implementation assumes
    # that the hierarchy is made up of nodes that optionally expose a
    # ``children`` attribute which is an iterable of child nodes.
    def _flatten(node):
        """Generator that yields a node and then all of its descendants."""
        try:
            yield node
        except Exception:
            # If we cannot iterate over node itself, just return
            return
        try:
            children = getattr(node, 'children', None)
        except Exception:
            children = None
        if children and isinstance(children, (list, tuple)):
            for child in children:
                yield from _flatten(child)
        elif children:
            # Fall back to using an iterator if possible
            try:
                for child in iter(children):
                    yield from _flatten(child)
            except Exception:
                pass

    # Determine the root node.  If the current object defines a ``root``
    # attribute use it; otherwise we try to use ``self`` itself.
    try:
        root = getattr(self, 'root', None)
    except Exception:
        root = None
    if root is None:
        root = self

    num_objects = 0
    good_objects = 0

    # Helper functions for validation
    def validate_object(obj):
        """Validate a single object using a user defined method if
        available, otherwise default to True."""
        if hasattr(self, '_validate_object'):
            try:
                return bool(self._validate_object(obj))
            except Exception:
                if show_warnings:
                    print(f"Warning: _validate_object raised an exception for {obj!r}")
                return False
        return True

    def check_digest(obj):
        """Check the digest of an object if possible.  The object is
        considered valid if it has a ``data`` attribute or a
        ``content`` attribute that can be hashed with sha256.  If the
        object defines a ``digest`` attribute this is compared with
        the computed one."""
        try:
            if hasattr(obj, 'digest'):
                expected = getattr(obj, 'digest')
                # Try to read the data that should be hashed
                data = getattr(obj, 'data', None)
                if data is None:
                    data = getattr(obj, 'content', None)
                if data is None:
                    # Fall back to the object's __dict__ representation
                    data = str(obj.__dict__).encode('utf-8')
                else:
                    if isinstance(data, str):
                        data = data.encode('utf-8')
                    elif isinstance(data, (bytes, bytearray)):
                        data = bytes(data)
                import hashlib
                actual_hash = hashlib.sha256(data).hexdigest()
                return expected == actual_hash
            else:
                # No digest defined, consider it valid
                return True
        except Exception:
            if show_warnings:
                print(f"Warning: could not verify digest for {obj!r}")
            return False

    try:
        for node in _flatten(root):
            num_objects += 1
            valid = True
            if validate_objects:
                valid = validate_object(node)
            if valid and check_digests:
                valid = check_digest(node)
            if valid:
                good_objects += 1
    except Exception as err:
        if show_warnings:
            print(f"Error during hierarchy validation: {err!r}")
        # Even if the traversal failed, return what we counted so far
        return num_objects, good_objects

    return num_objects, good_objects

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    # Resolve the desired root directory
    try:
        root_path = getattr(self, "root_path", None)
        if root_path is None:
            # Fall back to any stored attribute that may hold the path
            root_path = getattr(self, "path", None)
        if root_path is None:
            raise ValueError("No root path specified for OCFL storage.")
        from pathlib import Path
        root = Path(root_path).expanduser().resolve()
    except Exception as exc:
        raise ValueError(f"Unable to resolve root path: {exc}") from exc

    # Ensure we don't overwrite an existing OCFL root
    marker = root / ".ocfl_root"
    if root.exists():
        if marker.is_file():
            raise ValueError(f"An OCFL root already exists at '{root}'.")
        raise ValueError(f"Path '{root}' already exists and is not empty.")

    # Attempt to create the root directory structure
    try:
        root.mkdir(parents=True, exist_ok=False)
    except OSError as exc:
        raise ValueError(f"Could not create root directory '{root}': {exc}") from exc

    # Create the OCFL metadata file with the current version
    ocfl_version = "1.0"
    try:
        with marker.open("w", encoding="utf-8") as fp:
            fp.write(f'{{"ocfl_version":"{ocfl_version}"}}\n')
    except OSError as exc:
        raise ValueError(f"Could not write OCFL marker file at '{marker}': {exc}") from exc

    # Create a default subdirectory for objects (recommended but not required by spec)
    objects_dir = root / "objects"
    try:
        objects_dir.mkdir(exist_ok=False)
    except OSError as exc:
        # Not fatal – if the directory already exists we ignore it
        if exc.errno != 17:  # 17 = File exists
            raise ValueError(f"Could not create objects directory '{objects_dir}': {exc}") from exc

    # Store the resolved root in the instance for later reference
    setattr(self, "_ocfl_root", root)
    return self

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    try:
        if not isinstance(version, str):
            version = str(version)
        version = version.strip()
        if not version:
            return ""
    except Exception:
        return ""

    parts = version.split('.')
    if not parts:
        return version
    last = parts[-1]
    # Preserve leading zeros if present
    zero_len = len(last) - len(last.lstrip('0'))
    if zero_len < 1:
        try:
            num = int(last)
        except ValueError:
            return version
        new_last = str(num + 1)
    else:
        try:
            num = int(last.lstrip('0') or '0')
        except ValueError:
            return version
        new_num_str = str(num + 1)
        # Pad with zeros to maintain original width
        new_last = new_num_str.rjust(zero_len + len(new_num_str), '0')
    parts[-1] = new_last
    return '.'.join(parts)

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Ensure we have a root inventory to compare against.
    if not hasattr(self, "root_inventory") or not isinstance(self.root_inventory, dict):
        raise ValueError("Root inventory not available or not a dictionary")

    self.different_digests = {}  # key: item, value: list of (version, digest) tuples

    for dir_name in version_dirs:
        # Construct the path to the inventory file for this version.
        inv_path = os.path.join(self.base_dir, dir_name, "inventory.json")

        # The inventory file must exist.
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"Missing inventory file for version directory '{dir_name}'")

        # Load the inventory; it should be a mapping of item -> digest.
        try:
            with open(inv_path, "r", encoding="utf-8") as fh:
                inventory = json.load(fh)
        except Exception as exc:
            raise ValueError(f"Failed to read inventory from '{inv_path}': {exc}") from exc

        if not isinstance(inventory, dict):
            raise ValueError(f"Inventory at '{inv_path}' is not a dictionary")

        # Ensure the inventory contains all items from the root inventory.
        missing_items = set(self.root_inventory.keys()) - set(inventory.keys())
        if missing_items:
            raise ValueError(
                f"Inventory '{inv_path}' is missing items {sorted(missing_items)}"
            )

        # Check for digest mismatches and record them.
        for item, root_digest in self.root_inventory.items():
            version_digest = inventory.get(item)
            if version_digest is None:
                # This shouldn't happen because of the previous check, but guard anyway.
                continue
            if version_digest != root_digest:
                self.different_digests.setdefault(item, []).append(
                    (dir_name, version_digest)
                )

    return self

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    # Helper to merge two MappingNode values
    def _merge_mapping_nodes(node1, node2):
        """Recursively merge two MappingNode objects."""
        # Merge the list of key/value pair tuples in node1 and node2
        merged_pairs = deep_merge_nodes(node1.value + node2.value)
        return MappingNode(node1.tag, merged_pairs)

    result_map = {}
    order_keys = []
    key_obj_map = {}

    for key, val in nodes:
        try:
            key_id = key.value
        except AttributeError:
            key_id = str(key)

        if key_id not in key_obj_map:
            key_obj_map[key_id] = key
            order_keys.append(key_id)

        if key_id in result_map:
            existing_val = result_map[key_id]
            # If both values are MappingNode, deep merge
            if isinstance(existing_val, MappingNode) and isinstance(val, MappingNode):
                merged_val = _merge_mapping_nodes(existing_val, val)
                result_map[key_id] = merged_val
            else:
                # For non-mapping or mismatched types, the last value wins
                result_map[key_id] = val
        else:
            result_map[key_id] = val

    # Reconstruct list preserving original first-occurrence order
    merged_list = [(key_obj_map[k], result_map[k]) for k in order_keys]
    return merged_list

def parser_flags(parser):
    """Given an argparse.ArgumentParser instance, return its argument flags in a space‑separated string."""
    # Basic validation of the parser argument
    if parser is None or not hasattr(parser, "_actions"):
        raise ValueError("The supplied object is not a valid argparse.ArgumentParser instance.")
    flags = []
    # Iterate over all actions attached to the parser
    for action in parser._actions:
        # Some actions (e.g., positional arguments) have empty option_strings
        for opt in getattr(action, "option_strings", []):
            if opt:  # ignore empty strings
                flags.append(opt)
    return " ".join(flags)

def parse_arguments(*unparsed_arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    """
    import argparse

    # A base parser that can parse any arguments but does not define any options.
    base_parser = argparse.ArgumentParser(add_help=False)

    # Group arguments. The first non-option token starts a new subparser group.
    groups = {"global": []}
    current_group = "global"
    for token in unparsed_arguments:
        if token.startswith("-"):
            # Option or flag: belongs to the current group
            groups[current_group].append(token)
        else:
            # Non-option token: start a new subparser group
            current_group = token
            groups[current_group] = []

    # Parse each group of arguments using the base parser.
    results = {}
    for group_name, args in groups.items():
        try:
            # parse_known_args returns (Namespace, list_of_unknown_options)
            ns, _ = base_parser.parse_known_args(list(args))
        except Exception:
            ns = argparse.Namespace()
        results[group_name] = ns

    return results

