def parser_flags(parser):
    '''Given an argparse.ArgumentParser instance, return its argument flags in a space-separated string.'''
    if not parser:
        return ""
    flags = []
    seen = set()
    for action in getattr(parser, "_actions", []):
        for flag in action.option_strings:
            if flag not in seen:
                flags.append(flag)
                seen.add(flag)
    return " ".join(flags)

def _dictsum(dicts):
    """Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    counters = []
    for d in dicts:
        if isinstance(d, dict):
            counters.append(Counter(d))
    if not counters:
        return {}
    return dict(reduce(operator.add, counters))

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    try:
        if not isinstance(val, str):
            return False
        s = val.strip().lower()
        return s == '' or s == 'none' or s == 'null'
    except Exception:
        return False

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    if parser is None:
        raise ValueError("parser cannot be None")
    try:
        actions = parser._actions
    except AttributeError:
        raise TypeError("Expected an argparse.ArgumentParser instance")
    flags = []
    for action in actions:
        try:
            option_strings = action.option_strings
        except AttributeError:
            continue
        for flag in option_strings:
            flags.append(flag)
    return ' '.join(flags)

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int):
        raise TypeError(f"number must be an integer, got {type(number).__name__}")
    if not isinstance(alphabet, list) or not all(isinstance(ch, str) for ch in alphabet):
        raise TypeError("alphabet must be a list of single-character strings")
    if len(alphabet) < 2:
        raise ValueError("alphabet must contain at least two distinct symbols")
    if number < 0:
        raise ValueError("number must be non-negative")

    base = len(alphabet)
    # Convert number to base `base` digits
    digits = []
    n = number
    if n == 0:
        digits.append(alphabet[0])
    else:
        while n > 0:
            n, rem = divmod(n, base)
            digits.append(alphabet[rem])

    # digits are currently least significant first; reverse to get most significant first
    digits = digits[::-1]

    # Apply padding if requested
    if padding is not None:
        if not isinstance(padding, int) or padding < 0:
            raise ValueError("padding must be a non-negative integer or None")
        if len(digits) < padding:
            pad = [alphabet[0]] * (padding - len(digits))
            digits = pad + digits

    return ''.join(digits)

def _replace_register(flow_params, register_number, register_value):
    """
    Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number
    :return: The modified flow_params dictionary
    """
    if flow_params is None:
        return None
    if not isinstance(flow_params, dict):
        raise TypeError("flow_params must be a dictionary")

    def _replace_in_obj(obj):
        if isinstance(obj, dict):
            for key, value in obj.items():
                if key == register_value:
                    obj[key] = register_number
                # Recursively process nested structures
                if isinstance(value, (dict, list)):
                    _replace_in_obj(value)
        elif isinstance(obj, list):
            for item in obj:
                if isinstance(item, (dict, list)):
                    _replace_in_obj(item)

    try:
        _replace_in_obj(flow_params)
    except Exception as exc:
        raise RuntimeError(f"Error while replacing register values: {exc}") from exc

    return flow_params

def replace_dots(value, arg):
    """
    Replaces all occurrences of '.' in the input string with the provided arg.
    """
    if value is None:
        raise ValueError("value cannot be None")
    if not isinstance(value, str):
        raise TypeError(f"value must be a string, got {type(value).__name__}")
    arg_str = "" if arg is None else str(arg)
    return value.replace(".", arg_str)

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError("cls must be a class (type)")
    seen = set()
    queue = set([cls])
    while queue:
        c = queue.pop()
        seen.add(c)
        for s in c.__subclasses__():
            if s not in seen:
                queue.add(s)
    seen.discard(cls)
    return seen

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Validate alphabet
    if not isinstance(alphabet, list):
        raise TypeError("alphabet must be a list")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("alphabet should contain unique characters")
    base = len(alphabet)
    if base == 0:
        raise ValueError("alphabet cannot be empty")
    if base == 1:
        # Unary base: each occurrence counts as one
        if set(string) == {alphabet[0]}:
            return len(string)
        raise ValueError("string contains characters not allowed in unary alphabet")

    # Create mapping from character to digit value
    mapping = {ch: idx for idx, ch in enumerate(alphabet)}

    # Convert string to integer
    value = 0
    for ch in string:
        if ch not in mapping:
            raise ValueError(f"Character '{ch}' not in alphabet")
        value = value * base + mapping[ch]

    return value

def get_repo_archive(url: str, destination_path: Path) -> Path:
    """
    Given an url and a destination path, retrieve and extract .tar.gz archive
    which contains 'desc' file for each package.
    Each .tar.gz archive corresponds to an Arch Linux repo ('core', 'extra', 'community').

    Args:
        url: url of the .tar.gz archive to download
        destination_path: the path on disk where to extract archive

    Returns:
        a directory Path where the archive has been extracted to.
    """
    if not isinstance(url, str) or not url:
        raise ValueError("url must be a non-empty string")

    if not isinstance(destination_path, Path):
        raise TypeError("destination_path must be a pathlib.Path instance")

    # Ensure destination_path exists and is an empty directory
    if destination_path.exists():
        if not destination_path.is_dir():
            raise NotADirectoryError(f"{destination_path!s} exists but is not a directory")
        if any(destination_path.iterdir()):
            raise RuntimeError(f"destination_path {destination_path!s} must be empty")
    else:
        destination_path.mkdir(parents=True, exist_ok=True)

    # Download the archive to a temporary file
    tmp_fd, tmp_path = tempfile.mkstemp(suffix=".tar.gz")
    os.close(tmp_fd)
    try:
        with requests.get(url, stream=True, timeout=60) as r:
            r.raise_for_status()
            with open(tmp_path, "wb") as f:
                for chunk in r.iter_content(chunk_size=8192):
                    if chunk:
                        f.write(chunk)

        # Extract the tar.gz archive
        with tarfile.open(tmp_path, mode="r:gz") as tar:
            tar.extractall(path=destination_path)

    except Exception as exc:
        # Remove temporary file if extraction fails
        if os.path.exists(tmp_path):
            os.remove(tmp_path)
        raise
    else:
        # Clean up temporary file after successful extraction
        if os.path.exists(tmp_path):
            os.remove(tmp_path)

    return destination_path

def os_is_mac():
    """
    Checks if the os is macOS

    :return: True is macOS
    :rtype: bool
    """
    try:
        return os.uname().sysname == 'Darwin'
    except Exception:
        return False

def regex_dict(item):
    """
    Convert *.cpp keys to regex keys

    Given a dict where the keys are all filenames with wildcards, convert only
    the keys into equivalent regexes and leave the values intact.
    """
    if not isinstance(item, dict):
        raise TypeError("Expected a dictionary for 'item'")
    regexed = {}
    for key, value in item.items():
        if isinstance(key, str):
            # Escape special regex characters, then replace escaped '*' with '.*'
            pattern = '^' + re.escape(key).replace(r'\*', '.*') + '$'
            regexed[pattern] = value
        else:
            # Non-string keys are left untouched
            regexed[key] = value
    return regexed

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    # Strip leading and trailing single or double quotes
    return name.strip('"\'')

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import shlex
    import os

    # Ensure we have a text string to split
    if isinstance(s, bytes):
        try:
            text = s.decode('utf-8')
        except Exception:
            # Fallback decoding for bytes that might contain non-utf-8
            text = s.decode('utf-8', 'ignore')
    elif isinstance(s, str):
        text = s
    else:
        raise TypeError(f"Expected str or bytes, got {type(s)!r}")

    # Determine the POSIX flag based on the requested platform
    if platform == 'this':
        posix = os.name != 'nt'
    elif platform == 1:
        posix = True
    elif platform == 0:
        posix = False
    else:
        raise ValueError('platform must be 1 (POSIX), 0 (Windows/CMD), or "this"')

    # Delegate to shlex.split with the appropriate POSIX setting
    return shlex.split(text, posix=posix)

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import os
    import subprocess
    from pathlib import Path

    # validate archive existence
    if not os.path.exists(archive_path):
        raise FileNotFoundError(f"No such archive: {archive_path}")

    # determine destination directory
    tmp_path = Path(tmp_path).expanduser()
    base_name = os.path.basename(archive_path)

    # choose a default directory name based on archive type
    if base_name.endswith(".tar.gz"):
        dest_name = os.path.splitext(os.path.splitext(base_name)[0])[0]
    elif base_name.endswith(".tar.bz2"):
        dest_name = os.path.splitext(os.path.splitext(base_name)[0])[0]
    elif base_name.endswith(".zip"):
        dest_name = os.path.splitext(base_name)[0]
    else:
        raise ValueError(f"Unsupported archive format: {archive_path}")

    if filename:
        dest_name = filename

    dest_dir = tmp_path / dest_name

    try:
        # create destination directory
        dest_dir.mkdir(parents=True, exist_ok=False)
    except FileExistsError as exc:
        raise RuntimeError(f"Destination directory already exists: {dest_dir}") from exc

    # pick extraction command
    if base_name.endswith(".tar.gz") or base_name.endswith(".tar.bz2"):
        cmd = ["tar", "-xf", archive_path, "-C", str(dest_dir)]
    elif base_name.endswith(".zip"):
        cmd = ["unzip", "-q", archive_path, "-d", str(dest_dir)]
    else:
        # should never reach here due to earlier check
        raise RuntimeError(f"Unhandled archive format: {archive_path}")

    try:
        subprocess.run(cmd, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    except subprocess.CalledProcessError as exc:
        # clean up partially extracted files
        try:
            subprocess.run(["rm", "-rf", dest_dir], check=False)
        except Exception:
            pass
        raise RuntimeError(f"Extraction failed for {archive_path}") from exc

    # Return a file-url suitable for git
    return f"file://{dest_dir.resolve()}"

def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    try:
        result = subprocess.run(
            ['git', 'ls-files', '--others', '--ignored', '--exclude-standard'],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            check=True
        )
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"git ls-files failed: {e.stderr.strip()}") from e
    files = [line.strip() for line in result.stdout.splitlines() if line.strip()]
    files.sort()
    return ','.join(files)

def match(filename):
    """
    Check if the filename is a type that this module supports

    Args:
        filename: Filename to match

    Returns:
        False if not a match, True if supported
    """
    try:
        if not filename:
            return False
        _, ext = os.path.splitext(str(filename))
        return ext.lower() in {'.py', '.sh', '.bash'}
    except Exception:
        return False

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    # Handle None or "always"
    if frequency is None:
        return None
    if not isinstance(frequency, str):
        raise ValueError('Frequency must be a string or None')
    freq = frequency.strip()
    if freq.lower() == 'always':
        return None

    # Split into two parts: number and unit
    parts = freq.split()
    if len(parts) != 2:
        raise ValueError(f"Invalid frequency format: '{frequency}'")

    num_part, unit_part = parts
    if not num_part.isdigit():
        raise ValueError(f"Frequency number is not an integer: '{num_part}'")
    number = int(num_part)
    unit = unit_part.lower()

    # Map unit to timedelta keyword
    if unit in ('week', 'weeks'):
        return datetime.timedelta(weeks=number)
    elif unit in ('day', 'days'):
        return datetime.timedelta(days=number)
    elif unit in ('hour', 'hours'):
        return datetime.timedelta(hours=number)
    elif unit in ('minute', 'minutes'):
        return datetime.timedelta(minutes=number)
    elif unit in ('second', 'seconds'):
        return datetime.timedelta(seconds=number)
    elif unit in ('month', 'months'):
        # Approximate a month as 30 days
        return datetime.timedelta(days=number * 30)
    elif unit in ('year', 'years'):
        # Approximate a year as 365 days
        return datetime.timedelta(days=number * 365)

    raise ValueError(f"Unsupported time unit: '{unit}'")

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False
    host = host.strip()
    try:
        for family, socktype, proto, canonname, sockaddr in socket.getaddrinfo(host, None):
            if family == socket.AF_INET:
                ip = sockaddr[0]
                # IPv4 loopback starts with 127.
                if ip.startswith("127."):
                    return True
            elif family == socket.AF_INET6:
                ip = sockaddr[0]
                # Remove zone index if present
                if "%" in ip:
                    ip = ip.split("%", 1)[0]
                if ip == "::1":
                    return True
    except socket.gaierror:
        return False
    return False

def get_pattern(pattern, strip=True):
    """This method converts the given string to regex pattern"""
    if pattern is None:
        return None
    # Already compiled pattern
    if isinstance(pattern, re.Pattern):
        return pattern
    if hasattr(pattern, "pattern"):
        return pattern
    if isinstance(pattern, (bytes, bytearray)):
        try:
            return re.compile(pattern)
        except re.error as e:
            raise ValueError(f"Invalid regex pattern: {pattern}") from e
    if isinstance(pattern, str):
        if strip:
            pattern = pattern.strip()
        try:
            return re.compile(pattern)
        except re.error as e:
            raise ValueError(f"Invalid regex pattern: {pattern}") from e
    raise TypeError(f"Unsupported pattern type: {type(pattern).__name__}")

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Normalize inputs
    if not isinstance(commands, (list, str)):
        raise TypeError("commands must be a list or string")
    if isinstance(commands, str):
        commands = [commands]
    else:
        commands = list(commands)  # copy to avoid modifying caller list

    if isinstance(args, str):
        args = [args]
    elif not isinstance(args, list):
        raise TypeError("args must be a list or string")
    else:
        args = list(args)

    # Validate that each command is a string
    for cmd in commands:
        if not isinstance(cmd, str):
            raise TypeError(f"each command must be a string, got {type(cmd).__name__}")

    # Build stderr handling
    stderr_target = subprocess.DEVNULL if hide_stderr else None

    results = []
    for cmd in commands:
        full_cmd = [cmd] + args
        if verbose:
            print("Running command:", " ".join(full_cmd))
        try:
            result = subprocess.run(
                full_cmd,
                cwd=cwd,
                env=env,
                stderr=stderr_target,
                stdout=None,  # Let subprocess inherit stdout
                check=True
            )
            results.append(result)
        except subprocess.CalledProcessError as exc:
            # Enrich the error message with the command that failed
            err_msg = f"Command '{cmd}' failed with exit code {exc.returncode}"
            raise RuntimeError(err_msg) from exc

    return results

def is_ipv4(target):
    """ Test if IPv4 address or not """
    try:
        ipaddress.IPv4Address(target)
        return True
    except (ipaddress.AddressValueError, ValueError, TypeError):
        return False

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    try:
        # Use the provided dumper or fall back to yaml.Dumper
        yaml_dumper = dumper if dumper is not None else yaml.Dumper
        # Dump the object to a YAML string
        yaml_str = yaml.safe_dump(
            obj,
            Dumper=yaml_dumper,
            default_flow_style=False,
            allow_unicode=True,
        )
    except Exception as exc:
        raise ValueError(f"Error dumping object to YAML string: {exc}") from exc

    # In Python 2, yaml.safe_dump returns a byte string; convert to unicode
    if isinstance(yaml_str, bytes):
        try:
            return yaml_str.decode("utf-8")
        except Exception as exc:
            raise ValueError(f"Error decoding YAML byte string: {exc}") from exc

    return yaml_str

def make_array(shape, dtype=np.dtype("float32")):
    """Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple|int|list of int
        Shape of the array to create. Can be a single integer for a 1-D array.
    dtype : numpy.dtype or convertible
        Data-type of the array to create.
    Returns
    -------
    numpy.ndarray
        A new array with the requested shape and dtype.
    """
    # Validate and normalise `shape`
    if isinstance(shape, int):
        shape_tuple = (shape,)
    elif isinstance(shape, (list, tuple)):
        try:
            shape_tuple = tuple(int(dim) for dim in shape)
        except Exception as exc:
            raise ValueError(f"shape elements must be integers: {exc}")
    else:
        raise TypeError("shape must be an integer, list, or tuple of integers")

    # Validate and normalise `dtype`
    try:
        if not isinstance(dtype, np.dtype):
            dtype = np.dtype(dtype)
    except Exception as exc:
        raise TypeError(f"invalid dtype provided: {exc}")

    # Create and return the array
    return np.empty(shape_tuple, dtype=dtype)

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return a tuple of:
        - dict of configuration filename to corresponding parsed configuration,
        - sequence of logging.LogRecord instances containing any parse errors.
    """
    if overrides is None:
        overrides = {}

    import os
    import logging

    def _resolve_env(value):
        """Recursively replace ${VAR} placeholders with environment variables."""
        import re
        if isinstance(value, dict):
            return {k: _resolve_env(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [_resolve_env(v) for v in value]
        elif isinstance(value, str):
            pattern = r'\$\{([^}]+)\}'
            def repl(match):
                return os.getenv(match.group(1), match.group(0))
            return re.sub(pattern, repl, value)
        return value

    configs = {}
    errors = []

    for fname in config_filenames:
        try:
            with open(fname, 'r', encoding='utf-8') as f:
                raw = f.read()
            _, ext = os.path.splitext(fname)
            ext = ext.lower()
            parsed = None
            if ext in ('.yaml', '.yml'):
                import yaml
                parsed = yaml.safe_load(raw) or {}
            elif ext == '.json':
                import json
                parsed = json.loads(raw)
            elif ext == '.toml':
                import toml
                parsed = toml.loads(raw)
            elif ext == '.ini':
                import configparser
                from io import StringIO
                cp = configparser.ConfigParser()
                cp.read_file(StringIO(raw))
                parsed = {s: dict(cp.items(s)) for s in cp.sections()}
            else:
                raise ValueError(f"Unsupported file extension: {ext}")

            if resolve_env:
                parsed = _resolve_env(parsed)

            # Apply overrides, with overrides taking precedence
            merged = parsed.copy()
            merged.update(overrides)
            configs[fname] = merged

        except Exception as exc:
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=f"Failed to parse config '{fname}': {exc}",
                args=(),
                exc_info=None
            )
            errors.append(record)

    return configs, errors

def force_string(obj):
    """
    This function returns the bytes object corresponding to ``obj``
    in case it is a string using UTF-8. 
    """
    if isinstance(obj, str):
        return obj.encode('utf-8')
    else:
        return obj

@classmethod
    def protocol_handlers(cls, protocol_version=None):
        """Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        if protocol_version is not None and not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple of integers or None")

        # Aggregate handlers from the class and all its bases
        handlers = {}
        for base in reversed(cls.__mro__):
            base_handlers = getattr(base, "_bolt_handlers", {})
            if isinstance(base_handlers, dict):
                handlers.update(base_handlers)

        if protocol_version is not None:
            # Return only the specific handler if it exists
            if protocol_version in handlers:
                return {protocol_version: handlers[protocol_version]}
            return {}

        # Return a shallow copy to prevent accidental mutation
        return dict(handlers)

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    from zope.interface import Invalid
    import inspect

    # Helper to get interface names
    def get_method_names(i):
        try:
            return i.methods()
        except AttributeError:
            # Fallback for older zope.interface versions
            return [n for n, v in i.__dict__.items()
                    if isinstance(v, (sle).object)?]  # placeholder; actual implementation should use i.methods()
        return []

    def get_attribute_names(i):
        try:
            return i.attributes()
        except AttributeError:
            return [n for n, v in i.__dict__.items()
                    if isinstance(v, (sle).object)?]  # placeholder; actual implementation should use i.attributes()
        return []

    errors = []

    # 1. Check interface provisioning
    if not tentative:
        try:
            provided = iface.providedBy(candidate)
        except Exception:
            provided = False
        if not provided:
            errors.append('Candidate does not provide the interface: %s' % iface)

    # Helper to get candidate method signature length
    def _signature_length(method):
        try:
            sig = inspect.signature(method)
            # Count only positional or keyword-only parameters ignoring * and ** (they are variable)
            return len([p for p in sig.parameters.values()
                        if p.kind in (inspect.Parameter.POSITIONAL_OR_KEYWORD,
                                      inspect.Parameter.KEYWORD_ONLY)])
        except Exception:
            return None

    # 2. Check required methods
    for name in iface.methods():
        if not hasattr(candidate, name):
            errors.append(f"Missing method '{name}' required by interface {iface}")
            continue
        cand_attr = getattr(candidate, name)
        if not callable(cand_attr):
            errors.append(f"Attribute '{name}' of candidate is not callable")
            continue
        # Optional: compare signatures
        iface_method = iface[name] if hasattr(iface, name) else None
        if iface_method is not None:
            iface_sig_len = _signature_length(iface_method)
            cand_sig_len = _signature_length(cand_attr)
            if iface_sig_len is not None and cand_sig_len is not None:
                if iface_sig_len != cand_sig_len:
                    errors.append(f"Signature mismatch for method '{name}': expected {iface_sig_len} params, got {cand_sig_len}")

    # 3. Check required attributes
    for name in iface.attributes():
        if not hasattr(candidate, name):
            errors.append(f"Missing attribute '{name}' required by interface {iface}")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid(errors)

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if iface is None or candidate is None:
        raise TypeError("iface and candidate must not be None")

    # Determine the set of required members for the interface.
    required = set()
    if isinstance(iface, type):
        # For ABCs, use __abstractmethods__ if available.
        try:
            required.update(iface.__abstractmethods__)
        except AttributeError:
            pass
    elif isinstance(iface, (list, tuple, set)):
        required.update(iface)
    else:
        # Try to extract callable names if iface is an object or module.
        if hasattr(iface, "__abstractmethods__"):
            required.update(iface.__abstractmethods__)
        else:
            attrs = getattr(iface, "__dict__", {})
            for name, obj in attrs.items():
                if callable(obj) and not name.startswith("_"):
                    required.add(name)

    # Resolve the class of the candidate.
    target_cls = candidate if isinstance(candidate, type) else getattr(candidate, "__class__", None)
    if target_cls is None:
        raise TypeError("candidate must be a class or an instance of a class")

    # Check that every required member exists on the target class.
    missing = [name for name in required if not hasattr(target_cls, name)]
    if missing:
        msg = (
            f"Candidate class {target_cls.__name__} does not provide all required members "
            f"for interface {iface}. Missing: {', '.join(missing)}"
        )
        if tentative:
            return False
        raise ValueError(msg)

    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # Ensure bases are types
    for base in bases:
        if not isinstance(base, type):
            raise TypeError(f'Base {base!r} is not a type')
    # Gather candidate metaclasses: metaclasses of each base
    candidates = [base.__class__ for base in bases]
    # Include explicit metaclass if provided
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError(f'Explicit metaclass {explicit_mc!r} is not a type')
        candidates.append(explicit_mc)
    # If no bases and no explicit metaclass, default to type
    if not candidates:
        return type
    # Find the most derived metaclass that is a subclass of all others
    chosen = None
    for m in candidates:
        if all(issubclass(m, other) for other in candidates if other is not m):
            if chosen is None or issubclass(m, chosen):
                chosen = m
    if chosen is None:
        names = ', '.join(c.__name__ for c in candidates)
        raise TypeError(f"metaclass conflict: {names}")
    return chosen

def pop(self, key, default=__marker):
    """D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    try:
        val = self[key]
    except KeyError:
        if default is not __marker:
            return default
        raise
    else:
        del self[key]
        return val

def popitem(self):
        """Remove and return the `(key, value)` pair least frequently used."""
        # Ensure the cache is not empty
        if not self:
            raise KeyError('cache is empty')
        # Find the key with the smallest access frequency.
        # Assumes that each entry is stored as (value, frequency) or
        # otherwise the frequency can be extracted via a ``freq`` attribute.
        lfu_key = None
        lfu_freq = None
        for key in self:
            item = self[key]
            # Try to extract frequency from expected tuple form
            try:
                freq = item[1]
            except (IndexError, TypeError):
                # If the item is not a tuple or has no frequency,
                # treat its frequency as zero (i.e. least used).
                freq = 0
            if lfu_freq is None or freq < lfu_freq:
                lfu_freq = freq
                lfu_key = key
        # If we did not find any valid key, raise KeyError
        if lfu_key is None:
            raise KeyError('cache is empty')
        # Remove the least‑frequently used item
        value = self.pop(lfu_key)
        # Return the key and the underlying value (ignoring the stored frequency)
        if isinstance(value, tuple) and len(value) > 0:
            return (lfu_key, value[0])
        return (lfu_key, value)

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    # Preferred implementation: use an OrderedDict if available
    if hasattr(self, "_cache") and isinstance(self._cache, dict):
        try:
            return self._cache.popitem(last=False)
        except KeyError:
            raise KeyError("LRU cache is empty")
    # Fallback: assume the instance behaves like an OrderedDict
    try:
        # Retrieve first key since OrderedDict preserves insertion order
        key = next(iter(self))
    except StopIteration:
        raise KeyError("LRU cache is empty")
    # Get the associated value and delete the key
    value = self[key]
    del self[key]
    # Optionally, delete any auxiliary structures if needed
    if hasattr(self, "_access_order") and isinstance(self._access_order, list):
        # Remove the popped key from the access order tracking
        try:
            self._access_order.remove(key)
        except ValueError:
            pass
    return key, value

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    # Attempt to use this object's own popitem method if it accepts a `last` argument
    popitem = getattr(self, 'popitem', None)
    if popitem:
        try:
            return popitem(last=True)
        except TypeError:
            # Some popitem methods do not accept a `last` keyword (e.g., built‑in dict)
            try:
                return popitem()
            except KeyError as e:
                raise KeyError('no items to pop') from e
        except KeyError as e:
            raise KeyError('no items to pop') from e
    # If the object doesn't have popitem, look for a nested OrderedDict‑like attribute
    for attr in ('_cache', 'cache'):
        if hasattr(self, attr):
            container = getattr(self, attr)
            if hasattr(container, 'popitem'):
                try:
                    return container.popitem(last=True)
                except KeyError as e:
                    raise KeyError('no items to pop') from e
    # No suitable container found
    raise AttributeError('Unable to locate a suitable container for popitem')

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    if not self:
        raise KeyError('dictionary is empty')
    import random
    try:
        key = random.choice(list(self.keys()))
    except IndexError:
        raise KeyError('dictionary is empty')
    value = self.pop(key)
    return (key, value)

def parse(self, timestr, default=None,
              ignoretz=False, tzinfos=None, **kwargs):
    """Parse the date/time string into a :class:`datetime.datetime` object.

    See detailed docstring in the problem statement for full description.
    """
    # Defer imports to avoid module-level imports
    import datetime
    try:
        from dateutil.parser import parse as _dt_parse, ParserError
    except Exception as exc:
        raise ImportError(
            "dateutil.parser is required for the parse method "
            "but it could not be imported: %s" % exc
        ) from exc

    # Basic validation: timestr must be a string or bytes-like
    if timestr is None:
        return None
    if not isinstance(timestr, (str, bytes)):
        raise TypeError("timestr must be a string or bytes; got %r" % type(timestr))

    # Ensure timestr is a string
    if isinstance(timestr, bytes):
        try:
            timestr = timestr.decode()
        except Exception as exc:
            raise ValueError("timestr bytes could not be decoded: %s" % exc) from exc

    # Prepare keyword arguments for dateutil's parse
    parse_kwargs = kwargs.copy()
    parse_kwargs.setdefault("ignoretz", ignoretz)
    if default is not None:
        # Only pass a default if it is a datetime instance
        if not isinstance(default, datetime.datetime):
            raise TypeError(
                "default must be a datetime instance or None; "
                "got %r" % type(default)
            )
        parse_kwargs["default"] = default
    # tzinfos is ignored when ignoretz=True
    if tzinfos is not None and not ignoretz:
        parse_kwargs["tzinfos"] = tzinfos

    try:
        result = _dt_parse(timestr, **parse_kwargs)
        return result
    except ParserError as pe:
        # Re-raise ParserError to match original signature
        raise pe
    except (OverflowError, ValueError, TypeError) as exc:
        # Keep original exception types for consistency
        raise

def set_cut_chars(self, before: bytes, after: bytes) -> None:
    """Set the bytes used to delimit slice points.

    Args:
        before: Split file before these delimiters.
        after: Split file after these delimiters.
    """
    if not isinstance(before, bytes):
        raise TypeError(f"'before' must be bytes, got {type(before).__name__}")
    if not isinstance(after, bytes):
        raise TypeError(f"'after' must be bytes, got {type(after).__name__}")
    if len(before) == 0:
        raise ValueError("'before' cannot be empty")
    if len(after) == 0:
        raise ValueError("'after' cannot be empty")
    self._before_cut = before
    self._after_cut = after

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Private encrypted JSON payload
    try:
        data = json.loads(decode_if_bytes(request.body))
        if "encrypted_magic_envelope" in data:
            return True
    except Exception:
        pass
    # Public XML payload
    try:
        xml = etree.fromstring(encode_if_text(request.body))
        if xml.tag == MAGIC_ENV_TAG:
            return True
    except Exception:
        pass
    return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    if request is None:
        return False
    try:
        # Matrix API endpoints are typically prefixed with "/_matrix"
        path = getattr(request, "path", None) or getattr(request, "path_info", None)
        if isinstance(path, str) and path.startswith("/_matrix"):
            return True
        # Fallback: look for a header that Matrix uses
        headers = getattr(request, "headers", {})
        if isinstance(headers, dict):
            # Some Matrix clients set a custom header; this is optional
            if headers.get("X-Matrix-Request") is not None:
                return True
        # If the request body appears to be JSON and the Content-Type matches,
        # we treat it as a candidate Matrix request
        content_type = getattr(request, "content_type", None)
        if isinstance(content_type, str) and "application/json" in content_type.lower():
            return True
    except Exception:
        return False
    return False

def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    """
    if dt is None:
        return None
    if not isinstance(dt, datetime.datetime):
        raise TypeError("dt must be a datetime instance")
    # Ensure the datetime is timezone-aware in UTC
    if dt.tzinfo is None:
        # Assume naive times are UTC
        aware_dt = dt.replace(tzinfo=datetime.timezone.utc)
    else:
        aware_dt = dt.astimezone(datetime.timezone.utc)
    # Return a clean ISO‑8601 string without microseconds
    return aware_dt.strftime("%Y-%m-%dT%H:%M:%SZ")

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    try:
        from urllib.parse import urlsplit
        from urllib.request import Request, urlopen
        from urllib.error import URLError, HTTPError
    except Exception:
        return None

    try:
        scheme, netloc, path, query, fragment = urlsplit(url)
    except Exception:
        return None

    # Only http and https support the HEAD request in this context
    if scheme not in ("http", "https"):
        return None

    req = Request(url, method="HEAD")

    try:
        resp = urlopen(req)
    except (HTTPError, URLError):
        return None

    try:
        return resp.getheader("Content-Type")
    finally:
        try:
            resp.close()
        except Exception:
            pass

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    import re
    if not isinstance(tag, str):
        raise TypeError("'tag' expects a string")
    tag = tag.strip()
    if not tag:
        return False
    if len(tag) > 50:  # arbitrary maximum length
        return False
    pattern = re.compile(r'^[A-Za-z][A-Za-z0-9_-]*$')
    return bool(pattern.match(tag))

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversion - child nodes are not recursively processed.
    """
    if node is None:
        return {}
    result = {}
    for child in node:
        key = child.tag
        # If the key already exists, convert to or append to a list
        if key in result:
            existing = result[key]
            if isinstance(existing, list):
                existing.append(child)
            else:
                result[key] = [existing, child]
        else:
            result[key] = child
    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Basic validation of the input
    if not isinstance(url, str) or not url.strip():
        raise ValueError("The 'url' argument must be a non-empty string")
    # Normalize URL: remove any trailing slash
    base_url = url.rstrip("/")
    # Determine the relative path to the NodeInfo document
    if document_path:
        # Ensure it starts with a slash for proper combination
        rel_path = document_path if document_path.startswith("/") else "/" + document_path
    else:
        rel_path = "/.well-known/nodeinfo"
    # Build the full href
    href = f"{base_url}{rel_path}"
    # Construct the well-known JSON document
    well_known = {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                "href": href
            }
        ]
    }
    return well_known

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    # Extract host from handle
    try:
        host = handle.split("@")[1]
    except Exception:
        return None

    # Helper to fetch webfinger via given scheme
    def _fetch(scheme: str) -> Optional[str]:
        try:
            import urllib.request
            import urllib.parse
        except Exception:
            return None
        try:
            url = f"{scheme}://{host}/.well-known/webfinger?resource=acct:{urllib.parse.quote(handle)}"
            with urllib.request.urlopen(url, timeout=10) as resp:
                return resp.read().decode('utf-8', errors='ignore')
        except Exception:
            return None

    # Try HTTPS first, then fallback to HTTP
    doc = _fetch("https")
    if doc is not None:
        return doc
    return _fetch("http")

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        host = handle.split("@")[1]
    except AttributeError:
        logger.warning("retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle)
        return None
    document, code, exception = fetch_document(
        host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if document:
        return parse_diaspora_webfinger(document)
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None
    url = hostmeta.find_link(rels="lrdd").template.replace("{uri}", quote(handle))
    document, code, exception = fetch_document(url)
    if exception:
        return None
    return parse_diaspora_webfinger(document)

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    if not host:
        return None
    document, code, exception = fetch_document(host=host, path="/.well-known/host-meta")
    if exception or not document:
        return None
    try:
        xrd = XRD.parse_xrd(document)
    except Exception:
        return None
    return xrd

