@classmethod
    def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        # Ensure we have some content to work with
        if spec_content is None:
            raise IRValidatorException("Spec content must be provided")

        # If the content is already a dictionary, skip parsing
        if isinstance(spec_content, dict):
            data = spec_content
        else:
            # Attempt to parse YAML, allowing JSON as a fallback
            try:
                data = yaml.safe_load(spec_content)
            except Exception as exc:
                raise IRValidatorException(f"Failed to parse spec content: {exc}")

        # The spec must be a mapping
        if not isinstance(data, dict):
            raise IRValidatorException("Spec content must be a YAML mapping (dict)")

        # Determine required keys (can be overridden in subclass)
        required_fields = getattr(cls, 'REQUIRED_FIELDS', [])

        # Identify any missing mandatory fields
        missing = [field for field in required_fields if field not in data]
        if missing:
            raise IRValidatorException(f"Missing required fields in spec: {', '.join(missing)}")

        return data

def validate_from_file(cls, yaml_file=None):
    """
    Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if not yaml_file:
        raise IRValidatorException("yaml_file argument must be supplied")

    try:
        with open(yaml_file, 'r') as f:
            data = yaml.safe_load(f)
    except FileNotFoundError as fe:
        raise IRValidatorException(f"File not found: {yaml_file}") from fe
    except Exception as e:
        raise IRValidatorException(f"Problem reading YAML file: {e}") from e

    if not isinstance(data, dict):
        raise IRValidatorException("YAML content must be a mapping")

    required = getattr(cls, 'REQUIRED_KEYS', ['name', 'type'])
    missing = [key for key in required if key not in data]
    if missing:
        raise IRValidatorException(
            f"Missing mandatory keys in file {yaml_file}: {', '.join(missing)}"
        )

    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    visited = set()

    def _resolve(d):
        if id(d) in visited:
            raise RuntimeError("Circular include detected in spec files")
        visited.add(id(d))
        if not isinstance(d, dict):
            return d
        # If an 'include' key is present, merge its content into the current dict
        include = d.pop('include', None)
        if include is not None:
            if not isinstance(include, dict):
                raise ValueError("'include' value must be a dict")
            _resolve(include)
            for k, v in include.items():
                if k not in d:
                    d[k] = v
                else:
                    # Merge nested dicts, otherwise overwrite
                    if isinstance(d[k], dict) and isinstance(v, dict):
                        _resolve(d[k])
                        _resolve(v)
                        d[k].update(v)
                    else:
                        d[k] = v
        # Recursively resolve any nested includes
        for key, value in list(d.items()):
            if isinstance(value, dict):
                _resolve(value)
        return d

    return _resolve(parser_dict)

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    # Ensure we have a spec to pull from
    spec = getattr(self, "spec", None)
    if spec is None:
        raise AttributeError("The object does not have a 'spec' attribute.")
    # Iterate over all arguments defined in the scheme
    for arg in getattr(self, "args", []):
        # Skip items that are not option objects
        if not hasattr(arg, "name"):
            continue
        # Attempt to fetch the value from the spec
        try:
            if isinstance(spec, dict):
                value = spec.get(arg.name)
            else:
                value = getattr(spec, arg.name, None)
        except Exception:
            value = None
        # If no value in spec, fall back to the option's default
        if value is None:
            default_val = getattr(arg, "default", None)
            if default_val is None:
                # Guard against sentinel NoDefault if used in the framework
                try:
                    from .markers import NoDefault  # pragma: no cover
                except Exception:
                    NoDefault = object  # Fallback placeholder
                if isinstance(default_val, NoDefault):
                    default_val = None
            value = default_val
        # Handle nested dict options by merging defaults recursively
        try:
            from .option_types import DictOption  # pragma: no cover
        except Exception:
            DictOption = None
        if DictOption and isinstance(arg, DictOption) and isinstance(value, dict):
            # If the option has an associated scheme, merge its defaults
            scheme = getattr(arg, "scheme", None)
            if scheme and hasattr(scheme, "get_spec_defaults"):
                try:
                    sub_defaults = scheme.get_spec_defaults()
                    for sub_key, sub_val in sub_defaults.items():
                        # Only add if the key is missing or None
                        if sub_key not in value or value.get(sub_key) is None:
                            value[sub_key] = sub_val
                except Exception:
                    # Silently ignore any errors while merging sub defaults
                    pass
        defaults[arg.name] = value
    return defaults

def validate_arg_deprecation(self, cli_args, answer_file_args):
        """
        Validates and prints the deprecated arguments.

        :param cli_args: dict of arguments from command‑line
        :param answer_file_args: dict of arguments from answer files
        """
        # Ensure supplied arguments are dictionaries
        if not isinstance(cli_args, dict):
            cli_args = {}
        if not isinstance(answer_file_args, dict):
            answer_file_args = {}

        # The mapping of deprecated argument names to their current names should
        # be provided by the subclass as a dictionary attribute named
        # `deprecated_args`.  If the attribute does not exist or is not a dict,
        # simply skip validation.
        deprecated_map = getattr(self, "deprecated_args", {})
        if not isinstance(deprecated_map, dict):
            return

        # Helper to process a single source of arguments
        def process_source(source_name, args_dict):
            for old_name, new_name in deprecated_map.items():
                if old_name in args_dict:
                    # Issue a warning message
                    print(
                        f"[{source_name}] Deprecated argument '{old_name}' "
                        f"detected. Use '{new_name}' instead."
                    )
                    # If the new name isn't already present, inherit the value.
                    if new_name not in args_dict:
                        args_dict[new_name] = args_dict[old_name]
                    # Optionally, leave the old key in place – callers might rely
                    # on it – but they should use the new name moving forward.

        # Validate command‑line arguments
        process_source("CLI", cli_args)

        # Validate answer‑file arguments
        process_source("Answer file", answer_file_args)

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")

    # Find a mapping that contains command option specifications
    possible_attrs = ("command_options", "options_by_command", "_command_options", "commands")
    cmd_map = None
    for attr_name in possible_attrs:
        if hasattr(self, attr_name):
            cmd_map = getattr(self, attr_name)
            break

    if cmd_map is None:
        raise AttributeError("No command options mapping found on the instance")
    if not isinstance(cmd_map, dict):
        raise TypeError("The command options mapping must be a dictionary")

    try:
        # Return a shallow copy to avoid external modifications affecting the internal data
        return list(cmd_map[command_name])
    except KeyError as exc:
        raise KeyError(f"Command '{command_name}' not found in command options") from exc
    except Exception as exc:
        raise RuntimeError(f"Failed to retrieve options for command '{command_name}': {exc}") from exc

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Basic argument validation
    if command_name is None:
        raise ValueError("command_name must not be None")
    if argument_name is None:
        raise ValueError("argument_name must not be None")
    if not isinstance(command_name, (str, bytes)):
        raise TypeError(f"command_name must be a string, got {type(command_name).__name__}")
    if not isinstance(argument_name, (str, bytes)):
        raise TypeError(f"argument_name must be a string, got {type(argument_name).__name__}")

    # Retrieve the internal option specification mapping if it exists
    try:
        option_specs = getattr(self, "_option_specs", None)
    except Exception:
        # If the attribute cannot be safely retrieved, return None
        return None

    # Ensure the internal mapping is a dictionary
    if not isinstance(option_specs, dict):
        return None

    # Find the specification for the requested command
    command_spec = option_specs.get(command_name)
    if command_spec is None:
        return None

    # The command-specific spec is expected to be a dictionary mapping argument names to specs
    if not isinstance(command_spec, dict):
        return None

    # Return the specific option specification, or None if it does not exist
    return command_spec.get(argument_name)

def validate_requires_args(self, args):
        """
        Check if all the required arguments have been provided.
        """
        if args is None:
            raise ValueError("Arguments cannot be None.")
        # Determine the list of required argument names. Prefer an attribute named
        # `_required`, fall back to `required_args`, or an empty list if neither
        # exists.
        req_attrs = ("_required", "required_args")
        required = []
        for attr in req_attrs:
            if hasattr(self, attr):
                required = getattr(self, attr)
                break
        if not isinstance(required, (list, tuple)):
            raise ValueError("Required arguments should be a list or tuple.")
        missing = []
        # Accept mapping types (dict, SimpleNamespace) or objects with attributes.
        for key in required:
            if isinstance(args, dict):
                if key not in args or args[key] is None:
                    missing.append(key)
            else:
                try:
                    if getattr(args, key) is None:
                        missing.append(key)
                except AttributeError:
                    missing.append(key)
        if missing:
            raise ValueError(f"Missing required arguments: {', '.join(missing)}")

def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    # Attempt to treat args as mapping; if not, raise a descriptive error
    if not isinstance(args, dict):
        raise TypeError("args must be a mapping of argument names to values")

    matched = []

    for spec in options_spec:
        # Get condition and argument name, support dicts and objects
        cond = None
        name = None
        try:
            cond = getattr(spec, "required_when", None)
