def validate_length_args(self, args):
        """Check if value of arguments is not longer than length specified.

        :param args: The received arguments.
        """
        # iterate over arguments specification
        for arg_name, arg_spec in args.items():
            # each argument spec is expected to be a dictionary
            if not isinstance(arg_spec, dict):
                continue
            # get optional length constraint and value to validate
            length = arg_spec.get('length')
            value = arg_spec.get('value')
            if length is None or value is None:
                continue

            # validate length type
            if not isinstance(length, int):
                raise TypeError(
                    f"length for argument '{arg_name}' must be an int, got {type(length).__name__}"
                )
            if length < 0:
                raise ValueError(
                    f"length for argument '{arg_name}' must be non-negative, got {length}"
                )

            # try to compute the length of the provided value
            try:
                val_len = len(value)
            except TypeError:
                # value has no length; skip validation for this arg
                continue

            if val_len > length:
                raise ValueError(
                    f"argument '{arg_name}' length {val_len} exceeds maximum allowed {length}"
                )

def validate_choices_args(self, args):
        """Check if value of choice arguments is one of the available choices.

        :param args: The received arguments.
        """
        # The argument definitions are expected to be stored in self.parsed_yaml['args']
        arg_definitions = self.parsed_yaml.get('args', {})
        if not isinstance(arg_definitions, dict):
            # In case the YAML parser returned something else, skip validation
            return

        for arg_name, arg_attrs in arg_definitions.items():
            # Ensure we are dealing with a dictionary that may contain 'choices'
            if not isinstance(arg_attrs, dict) or 'choices' not in arg_attrs:
                continue
            choices = arg_attrs.get('choices')
            # We expect choices to be an iterable of allowed values
            if choices is None:
                continue
            if not isinstance(choices, (list, tuple, set)):
                # Invalid configuration; skip or raise a warning
                continue

            # If the argument was supplied, validate its value
            if arg_name in args:
                value = args[arg_name]
                if value not in choices:
                    allowed = ", ".join(map(str, choices))
                    raise ValueError(
                        f"Argument '{arg_name}' has invalid value '{value}'. "
                        f"Allowed values: {allowed}"
                    )

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure args is a sequence (but avoid treating strings as a sequence of chars)
    if not isinstance(args, (list, tuple)):
        raise TypeError(f"args must be a sequence, got {type(args).__name__}")

    # Retrieve minimum and maximum bounds from the instance.  They may be
    # named ``min_``/``max_`` or ``min``/``max`` – fall back to None if not
    # defined.
    min_val = getattr(self, "min_", None)
    max_val = getattr(self, "max_", None)
    if min_val is None:
        min_val = getattr(self, "min", None)
    if max_val is None:
        max_val = getattr(self, "max", None)

    # At least one of minimum or maximum must be provided; otherwise we cannot
    # validate anything meaningful.
    if min_val is None and max_val is None:
        raise AttributeError(
            "Neither 'min/' 'min_' nor 'max/' 'max_' attributes are defined on the instance"
        )

    for idx, value in enumerate(args):
        # Skip None values – they are considered missing arguments and are
        # allowed to pass validation.  Adjust behaviour if a different policy
        # is required.
        if value is None:
            continue

        # Comparisons must be supported; if not, raise a clear TypeError.
        try:
            if min_val is not None and value < min_val:
                raise ValueError(
                    f"Argument at position {idx} ({value}) is less than the minimum "
                    f"allowed value {min_val}"
                )
            if max_val is not None and value > max_val:
                raise ValueError(
                    f"Argument at position {idx} ({value}) exceeds the maximum "
                    f"allowed value {max_val}"
                )
        except TypeError as exc:
            raise TypeError(
                f"Cannot compare argument at position {idx} ({value}) "
                f"with boundary values (min={min_val}, max={max_val})"
            ) from exc

    return args

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Defensive handling of various input types
    if args is None:
        return {}, {}

    # Convert a list of (key, value) tuples to a flat dict
    if isinstance(args, list):
        try:
            flat_args = {k: v for k, v in args}
        except Exception:
            raise ValueError("args as list must contain (key, value) tuples")
    elif isinstance(args, dict):
        flat_args = args.copy()
    else:
        raise TypeError("args must be a dict or a list of (key, value) tuples")

    # Define a set of keys that are considered control arguments.
    # These typically control the processor itself rather than being
    # passed down to the Ansible playbooks.  The set can be extended
    # by subclasses or overridden if necessary.
    control_keys = {
        'action', 'destroy', 'config', 'subcommand', 'help',
        'debug', 'verbose', 'dry_run', 'output', 'plan',
        'infra', 'environment', 'name'
    }

    control_args = {}
    nested_args = {}

    for key, value in flat_args.items():
        if key in control_keys or key.startswith('control_'):
            control_args[key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")
    if not extra_vars:
        return vars_dict
    # Support a single dictionary
    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
        return vars_dict
    # Support an iterable of dictionaries (typically a list)
    try:
        iterator = iter(extra_vars)
    except TypeError:
        raise TypeError("extra_vars must be a dict, list, or iterable of dicts")
    for item in iterator:
        if not isinstance(item, dict):
            raise TypeError("All items in extra_vars must be dictionaries")
        vars_dict.update(item)
    return vars_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    if not isinstance(values_dict, dict):
        raise TypeError("values_dict must be a dictionary")

    # Determine the list of option objects for the given parser.
    options = None
    if hasattr(self, "parsers"):
        options = self.parsers.get(parser_name) if isinstance(self.parsers, dict) else None
    if options is None:
        # Try to look up an attribute with the parser name directly.
        options = getattr(self, parser_name, None)

    if options is None:
        raise ValueError(f"Unknown parser name: {parser_name}")

    # Ensure options is iterable.
    try:
        iterable = iter(options)
    except TypeError:
        iterable = [options]

    for opt in iterable:
        # Prefer a `name` attribute; fallback to key 'name'.
        name = getattr(opt, "name", None)
        if name is None and isinstance(opt, dict):
            name = opt.get("name")
        if not name:
            continue  # skip options without a recognizable name

        if name not in values_dict:
            continue  # nothing to convert for missing value

        # Resolve the converter; if none provided, keep string as-is.
        converter = getattr(opt, "convert", None)
        if converter is None and isinstance(opt, dict):
            converter = opt.get("convert")
        if not callable(converter):
            converter = lambda x: x

        try:
            values_dict[name] = converter(values_dict[name])
        except Exception as exc:
            raise ValueError(f"Failed to convert argument '{name}' for parser '{parser_name}': {exc}") from exc

    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Find possible spec files
    spec_file = os.path.join(plugin_dir, "plugin.json")
    if not os.path.isfile(spec_file):
        # Try common alternatives
        candidates = [
            "plugin-spec.json",
            "spec.json",
            "plugin.yaml",
            "plugin.yml",
            "spec.yaml",
            "spec.yml",
        ]
        for name in candidates:
            path = os.path.join(plugin_dir, name)
            if os.path.isfile(path):
                spec_file = path
                break
        else:
            # No spec file found
            return {}

    try:
        with open(spec_file, "r", encoding="utf-8") as f:
            if spec_file.lower().endswith((".yaml", ".yml")):
                try:
                    import yaml
                except Exception:
                    # yaml is missing, cannot parse
                    return {}
                data = yaml.safe_load(f)
            else:
                data = json.load(f)
    except Exception:
        # Any error reading/parsing the spec results in an empty dict
        return {}

    def _flatten(obj, parent_key="", sep="."):
        items = {}
        if isinstance(obj, dict):
            for k, v in obj.items():
                new_key = f"{parent_key}{sep}{k}" if parent_key else k
                items.update(_flatten(v, new_key, sep=sep))
        elif isinstance(obj, list):
            for idx, val in enumerate(obj):
                new_key = f"{parent_key}{sep}{idx}" if parent_key else str(idx)
                items.update(_flatten(val, new_key, sep=sep))
        else:
            items[parent_key] = obj
        return items

    return _flatten(data)
